import 'dart:convert';

import '../../domain/entities/live_update.dart';
import '../../domain/entities/exam_category.dart';

/// Wire format for `live_feed_v1.json`.
///
/// Parsing is total: a single malformed row is skipped rather than failing the
/// whole feed. On result day the feed is generated by a cron job at 09:11 and
/// read by 10M devices at 09:12 — one bad row must not blank the screen.
abstract final class LiveFeedDto {
  static LiveFeed parse(String body) {
    final decoded = jsonDecode(body);
    if (decoded is! Map<String, dynamic>) {
      throw const FormatException('Live feed must be a JSON object.');
    }

    final generatedAt = _tryDate(decoded['generated_at']);
    final revision = _tryInt(decoded['revision']) ?? 0;
    final rawUpdates = decoded['updates'];

    // The document's *shape* is not optional. A 200 body without an `updates`
    // array — a rate-limit object, an error page that happens to be JSON —
    // used to parse as a VALID EMPTY feed: the repository then overwrote the
    // good Hive snapshot with nothing, and its error-attach catch never fired
    // because parse did not throw. Row-level tolerance below stays; a missing
    // or non-list `updates` is a hard FormatException so the stale-but-real
    // cache survives and the failure is reported.
    if (rawUpdates is! List) {
      throw const FormatException('Live feed has no "updates" array.');
    }

    final updates = <LiveUpdate>[];
    for (final row in rawUpdates) {
      if (row is! Map) continue;
      // A single malformed row must be skipped, never allowed to abort the
      // whole document: one bad record used to blank the entire radar.
      try {
        final update = _parseRow(row.cast<String, dynamic>());
        if (update != null) updates.add(update);
      } catch (_) {
        continue;
      }
    }

    updates.sort((a, b) => b.publishedAt.compareTo(a.publishedAt));

    return LiveFeed(
      generatedAt: generatedAt,
      updates: List.unmodifiable(updates),
      revision: revision,
      sources: _parseSources(decoded['sources']),
    );
  }

  /// Per-commission health. Total by design: a malformed entry is skipped, so a
  /// producer bug degrades the provenance panel instead of blanking the feed.
  static List<SourceHealth> _parseSources(Object? raw) {
    if (raw is! List) return const [];
    final out = <SourceHealth>[];
    for (final entry in raw) {
      if (entry is! Map) continue;
      try {
        final id = entry['id'];
        final label = entry['label'];
        final status = entry['status'];
        if (id is! String || label is! String || status is! String) continue;
        out.add(
          SourceHealth(
            id: id,
            label: label,
            status: status,
            rows: _tryInt(entry['rows']) ?? 0,
            homepage: _tryUrl(entry['homepage']),
            note: entry['note'] is String ? entry['note'] as String : null,
            checkedAt: _tryDate(entry['checked_at']),
          ),
        );
      } catch (_) {
        // A malformed source entry degrades provenance, not the feed.
        continue;
      }
    }
    return List.unmodifiable(out);
  }

  static LiveUpdate? _parseRow(Map<String, dynamic> row) {
    final examId = row['exam_id'];
    final examName = row['exam_name'];
    if (examId is! String || examName is! String) return null;

    // Every string field below is read defensively: a publisher sending a
    // number where a string belongs used to throw TypeError and kill the feed.
    final categoryRaw = row['category'];
    final category = ExamCategory.fromId(
      categoryRaw is String ? categoryRaw : null,
    );
    if (category == null) return null;

    final publishedAt = _tryDate(row['published_at']);
    if (publishedAt == null) return null;

    final statusRaw = row['status'];
    final status = UpdateStatus.fromId(statusRaw is String ? statusRaw : null);
    final contextRaw = row['context'];
    final context = contextRaw is String ? contextRaw.trim() : null;
    final indexVersionRaw = row['index_version'];

    return LiveUpdate(
      examId: examId,
      category: category,
      examName: examName,
      contextLine: context != null && context.isNotEmpty
          ? context
          : 'Tap for details',
      status: status,
      publishedAt: publishedAt,
      pdfSizeLabel: row['pdf_size'] is String
          ? row['pdf_size'] as String
          : null,
      mirrorLatencyMs: _tryInt(row['mirror_latency_ms']),
      expiresAt:
          _tryDate(row['expires_at']) ?? _defaultExpiry(status, publishedAt),
      // Link-only: the official document/page stays on the commission's server.
      officialPdf: _tryUrl(row['official_pdf']),
      officialPage: _tryUrl(row['official_page']),
      // The content hash of the published index, if there is one. Part of the
      // CDN path, so dropping it silently would make every lookup 404.
      // Non-empty guard: `index_available: true` with a forgotten version
      // string used to build a guaranteed-404 URL (`examId__rolls.json.gz`),
      // which was then memoised for the session as "not published" — for an
      // exam the feed itself advertised as published.
      indexVersion:
          row['index_available'] == true &&
              indexVersionRaw is String &&
              indexVersionRaw.trim().isNotEmpty
          ? indexVersionRaw
          : null,
      rollCount: _tryInt(row['roll_count']),
      // Absent is normal and honest: most notices do not state these.
      examDate: _tryDateOnly(row['exam_date']),
      resultDate: _tryDateOnly(row['result_date']),
      deadline: _tryDateOnly(row['deadline']),
      // Structured facts, only when the notice stated them.
      vacancy: _tryInt(row['vacancy']),
      fee: row['fee'] is String && (row['fee'] as String).trim().isNotEmpty
          ? (row['fee'] as String).trim()
          : null,
    );
  }

  /// A calendar date (`YYYY-MM-DD`) as LOCAL midnight.
  ///
  /// `DateTime.parse` on a bare date yields UTC midnight, which renders as the
  /// *previous* day in any negative-offset timezone — a deadline would show one
  /// day early. Dates carry no time, so they are pinned to the local day.
  static DateTime? _tryDateOnly(Object? raw) {
    if (raw is! String) return null;
    final parsed = DateTime.tryParse(raw.trim());
    if (parsed == null) return null;
    return DateTime(parsed.year, parsed.month, parsed.day);
  }

  /// Fallback TTL per status, used when the publisher omits `expires_at`.
  ///
  /// These are deliberately short. A "RESULT OUT" banner that never expires is
  /// misinformation; the publisher can override any of them per row.
  static DateTime _defaultExpiry(UpdateStatus status, DateTime publishedAt) {
    // Must match `TTL_HOURS` in tools/publish_feed.mjs. These were originally
    // 48h/36h/12h, which expired almost every real SSC notice the moment it was
    // published — a declared result is the current state of that exam for weeks.
    final ttl = switch (status) {
      UpdateStatus.resultOut => const Duration(days: 30),
      UpdateStatus.admitCardLive => const Duration(days: 21),
      UpdateStatus.formClosing => const Duration(days: 7),
      // Matches publish_feed.mjs: a vacancy stays useful while its window is
      // open, which is weeks, not days.
      UpdateStatus.notification => const Duration(days: 60),
      UpdateStatus.answerKey => const Duration(days: 30),
      UpdateStatus.awaited => const Duration(days: 90),
    };
    return publishedAt.add(ttl);
  }

  static DateTime? _tryDate(Object? value) {
    if (value is! String || value.isEmpty) return null;
    return DateTime.tryParse(value)?.toLocal();
  }

  /// Only absolute http(s) links are accepted: a relative or `javascript:` href
  /// would be opened by the OS with no way back.
  static String? _tryUrl(Object? value) {
    if (value is! String) return null;
    final uri = Uri.tryParse(value);
    if (uri == null || !uri.isAbsolute) return null;
    if (uri.scheme != 'https' && uri.scheme != 'http') return null;
    return value;
  }

  static int? _tryInt(Object? value) {
    if (value is int) return value;
    // `toInt()` throws UnsupportedError on Infinity/NaN, which a JSON payload
    // can carry as `1e999`; reject non-finite values instead of crashing.
    if (value is num) return value.isFinite ? value.toInt() : null;
    if (value is String) return int.tryParse(value);
    return null;
  }
}

/// Serialises the on-device copy so a cold boot is one Hive read, not one HTTP
/// call. Kept in the same shape as the wire format so there is exactly one
/// parser to maintain.
abstract final class LiveFeedStore {
  static const key = 'feed';

  static Map<String, dynamic> toJson(LiveFeed feed) => {
    'generated_at': feed.generatedAt?.toIso8601String(),
    'revision': feed.revision,
    if (feed.sources.isNotEmpty)
      'sources': [
        for (final s in feed.sources)
          {
            'id': s.id,
            'label': s.label,
            'status': s.status,
            'rows': s.rows,
            if (s.homepage != null) 'homepage': s.homepage,
            if (s.note != null) 'note': s.note,
            if (s.checkedAt != null)
              'checked_at': s.checkedAt!.toIso8601String(),
          },
      ],
    'updates': [
      for (final u in feed.updates)
        {
          'exam_id': u.examId,
          'category': u.category.id,
          'exam_name': u.examName,
          'context': u.contextLine,
          'status': u.status.id,
          // UTC, explicitly: the wire format carries an offset, but a local
          // toIso8601String() round-trip through the cache loses it, shifting
          // every age label and expiry by the zone delta if the device's
          // timezone ever changes.
          'published_at': u.publishedAt.toUtc().toIso8601String(),
          // Without this the cached row re-parsed with the default 30-day TTL,
          // silently resurrecting a row the publisher had already retired.
          if (u.expiresAt != null)
            'expires_at': u.expiresAt!.toUtc().toIso8601String(),
          if (u.pdfSizeLabel != null) 'pdf_size': u.pdfSizeLabel,
          if (u.mirrorLatencyMs != null) 'mirror_latency_ms': u.mirrorLatencyMs,
          if (u.officialPdf != null) 'official_pdf': u.officialPdf,
          if (u.officialPage != null) 'official_page': u.officialPage,
          if (u.indexVersion != null) ...{
            'index_available': true,
            'index_version': u.indexVersion,
          },
          if (u.rollCount != null) 'roll_count': u.rollCount,
        },
    ],
  };

  static LiveFeed? fromDynamic(Object? raw) {
    if (raw == null) return null;
    try {
      final asString = raw is String ? raw : jsonEncode(raw);
      return LiveFeedDto.parse(asString);
    } catch (_) {
      return null;
    }
  }
}

/// Helpers shared by the UI.
extension LiveUpdateFormatting on LiveUpdate {
  /// A compact age that reads correctly aloud and still means something after
  /// a week.
  ///
  /// The earlier format returned "now" / "621d": screen readers announced
  /// "now ago", and a notice from 2025 showed a bare day count with no hint of
  /// the date. This one always carries a unit word and falls back to the
  /// publication date after a week.
  String ageLabel([DateTime? now]) {
    final delta = (now ?? DateTime.now()).difference(publishedAt);
    if (delta.inSeconds < 60) return 'just now';
    if (delta.inMinutes < 60) return '${delta.inMinutes}m ago';
    if (delta.inHours < 24) return '${delta.inHours}h ago';
    if (delta.inDays < 8) return '${delta.inDays}d ago';
    return '${publishedAt.day} ${_months[publishedAt.month - 1]}';
  }

  static const _months = [
    'Jan',
    'Feb',
    'Mar',
    'Apr',
    'May',
    'Jun',
    'Jul',
    'Aug',
    'Sep',
    'Oct',
    'Nov',
    'Dec',
  ];
}
